    const why = /\b(?:because|so that|since|therefore|which|to (?:detect|prevent|reduce|avoid|identify|maintain|protect|limit|support|preserve|confirm|distinguish|control|relieve|restore|monitor|assess))\b/i;
    const nursing = (Array.isArray(items) ? items : []).map((item) => why.test(String(item))
      ? String(item)
      : `${clean(item).replace(/[.;]+$/, "")} because ${patch.mechanism}.`);
    const complication = complicationParts(patch.complications, patch.name)[0];
    while (nursing.length < 5) nursing.push(`Trend the disease-specific findings of ${patch.hallmark} and escalate immediately for ${complication} because ${patch.mechanism}.`);
    if (!patch.acute || nursing.length < 3) return nursing;
    const index = nursing.findIndex((item) => /\b(?:escalate|activate|emergency|rapid response|notify immediately|call 911)\b/i.test(String(item)));
